    b=open(f'g-{n}.pgm','rb').read()
    p=b.split(b'\n',3); w,h=map(int,p[1].split()); return w,h,p[3]
def underl(px,w,h,t,l,wd,ht):
    best=0
    for y in range(t+ht-6,t+ht+4):
        if y>=h: break
        row=px[y*w+l:y*w+l+wd]
        best=max(best,sum(1 for c in row if c<128)/max(1,wd))
    return best>0.85
CN=['LCR','NL','Seedlings first observed','First flowering Resp','First flowering Seed','First fruiting Resp','First fruiting Seed','Primary','Secondary']
pages={}; diag=[]
for pg in re.finditer(r'<page number="(\d+)"(.*?)</page>',x,re.S):
    n=int(pg.group(1)); body=pg.group(2)
    items=[]
    for m in re.finditer(r'<text top="(\d+)" left="(\d+)" width="(\d+)" height="(\d+)" font="(\d+)">(.*?)</text>',body):
        items.append([int(m.group(1)),int(m.group(2)),int(m.group(3)),int(m.group(4)),m.group(6)])
    hd={}
    for t,l,w,h,s in items:
        s2=re.sub('<.*?>','',s).strip()
        if s2 in('LCR','NL','Primary','Secondary','first observed','Resp','Seed'): hd.setdefault(s2,[]).append((t,l))
    if 'LCR' not in hd: continue
    htop=max(t for t,l in hd['LCR'])
    def g(k,i=0): return sorted([l for t,l in hd[k] if abs(t-htop)<5])[i]
    cols=[g('LCR'),g('NL'),[l for t,l in hd['first observed'] if abs(t-htop)<10][0],g('Resp'),g('Seed'),g('Resp',1),g('Seed',1),g('Primary'),g('Secondary')]
    W,H,px=load(n)
    data=[i for i in items if i[0]>htop+5 and i[0]<1095]
    left=[i for i in data if i[1]<cols[0]-10]
    vals=[i for i in data if i[1]>=cols[0]-10 and html.unescape(re.sub('<.*?>','',i[4])).strip()]
    # left lines
    lines={}
    for t,l,w,h,s in left:
        k=next((k for k in lines if abs(k-t)<=2),t); lines.setdefault(k,[]).append((l,s))
    recs=[]
    for t in sorted(lines):
        raw=''.join(s for l,s in sorted(lines[t]))
        txt=re.sub(r'\s+',' ',html.unescape(re.sub('<.*?>','',raw))).strip()
        if not txt: continue
        bold='<b>' in raw and '<i>' not in raw
        if bold and txt.isupper(): recs.append({'type':'group','txt':txt,'t':[t]})
        elif bold: recs.append({'type':'family','txt':txt,'t':[t]})
        elif re.match(r'(var|subsp|cv)\b',txt) and recs and recs[-1]['type']=='sp':
            recs[-1]['txt']+=' '+txt; recs[-1]['t'].append(t)
        elif 'pk.pf' in txt and recs and recs[-1]['type']=='sp':
            recs[-1]['note']=(recs[-1].get('note','')+' '+txt).strip(); recs[-1]['t'].append(t)
        else: recs.append({'type':'sp','txt':txt,'t':[t],'cells':{}})
    # merge value tokens horizontally
    vl={}
    for it in vals:
        k=next((k for k in vl if abs(k-it[0])<=2),it[0]); vl.setdefault(k,[]).append(it)
    toks=[]
    for t,its in vl.items():
        its.sort(key=lambda i:i[1]); cur=None
        for it in its:
            if cur and it[1]-(cur[1]+cur[2])<5:
                cur[2]=it[1]+it[2]-cur[1]; cur[4]+=it[4]
            else:
                cur=list(it); toks.append(cur)
    sps=[r for r in recs if r['type']=='sp']
    for t,l,w,h,s in toks:
        txt=html.unescape(re.sub('<.*?>','',s)).strip()
        b=re.sub(r'<b>/</b>','/',s); bold=bool(re.search(r'<b>[^<]*[0-9A-Za-z]',b))
        if bold: txt='**'+txt+'**'
        u=underl(px,W,H,t,l,w,h)
        d=[abs(l-c) for c in cols]; k=min(range(9),key=lambda i:d[i])
        if u:
            c=l+w/2
            if c<cols[5]-5: ks=[3,4]
            elif c<cols[7]-5: ks=[5,6]
            else: ks=[7,8]
            txt='<u>'+txt+'</u>'
        elif d[k]<=8: ks=[k]
        else:
            cc=[cl+14 for cl in cols]; c=l+w/2
            k2=min(range(9),key=lambda i:abs(c-cc[i])); ks=[k2]
            diag.append((n,t,txt,l,w,CN[k],CN[k2]))
        # find record
        best=None;bd=1e9
        for r in sps:
            lo,hi=min(r['t'])-3,max(r['t'])+3
            dd=0 if lo<=t<=hi else min(abs(t-lo),abs(t-hi))
            if dd<bd: bd=dd;best=r
        if bd>8: diag.append(('FAR',n,t,txt,best['txt'] if best else None,bd))
        for kk in ks:
            if kk in best['cells']: diag.append(('DUP',n,t,txt,best['txt'],CN[kk],best['cells'][kk])); best['cells'][kk]+=' '+txt
            else: best['cells'][kk]=txt
    pages[n]=recs
json.dump({str(k):v for k,v in pages.items()},open('recs.json','w'),ensure_ascii=False)
for d in diag: print(d)
