import subprocess,re,unicodedata,json
P='data/papers_test/pdf_done/Muir et al 2014 AustJBot_obligate seeder juvenile.pdf'
def col(n,x,w,y=50,h=740):
    return subprocess.run(['pdftotext','-layout','-f',str(n),'-l',str(n),'-x',str(x),'-y',str(y),'-W',str(w),'-H',str(h),P,'-'],capture_output=True,text=True).stdout
