for n in (8,9,10):
    ents=[]
    for x,w in ((0,298),(298,262)):
        t=col(n,x,w)
        t=unicodedata.normalize('NFKC',t)
        lines=t.split('\n')
        if n==8:
            # skip until References header in whichever column
            if 'References' in t:
                i=[k for k,l in enumerate(lines) if l.strip()=='References'][0]; lines=lines[i+1:]
            else: continue
        if n in (9,10): lines=lines[1:]  # running head
        for l in lines:
            if not l.strip(): continue
            if re.match(r'^\S',l): ents.append(l.strip())
            elif ents:
